 const downloadTaskTemplate=()=>{const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['Username','Kiểu công việc','Tên công việc','Mô tả','Deadline (dd/mm/yyyy)'],['nhanvien1','Nhập kiểu công việc','Ví dụ: Kiểm tra đơn mới','Kiểm tra và cập nhật trạng thái','15/11/2026']] ),'Giao viec');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['HƯỚNG DẪN'],['Mỗi dòng là một công việc. Username cần trùng với tài khoản nhân viên.'],['Admin tự nhập kiểu công việc phù hợp, ví dụ: Gọi khách, Kiểm tra đơn, Đóng gói.'],['Deadline dùng định dạng dd/mm/yyyy và phải thuộc tháng/năm đang chọn.']]),'Huong dan');XLSX.writeFile(wb,'MauGiaoViec.xlsx')};
  const importTaskFile=async(file:File)=>{setError('');try{const workbook=XLSX.read(await file.arrayBuffer(),{cellDates:true});const sheetName=workbook.SheetNames[0];if(!sheetName||!workbook.Sheets[sheetName])throw new Error('Tệp Excel không có trang tính dữ liệu.');const rows=XLSX.utils.sheet_to_json<unknown[]>(workbook.Sheets[sheetName],{header:1,raw:true,defval:''});const normalize=(value:unknown)=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase().trim();const headers=(rows[0]||[]).map(normalize);const find=(...names:string[])=>headers.findIndex(h=>names.includes(h));const userCol=find('username','ten dang nhap'),typeCol=find('kieu cong viec'),titleCol=find('ten cong viec','cong viec'),descriptionCol=find('mo ta','mo ta / yeu cau'),deadlineCol=find('deadline (dd/mm/yyyy)','deadline');if(userCol<0||typeCol<0||titleCol<0||deadlineCol<0)throw new Error('File cần có các cột Username, Kiểu công việc, Tên công việc và Deadline (dd/mm/yyyy).');const records=rows.slice(1).filter(row=>Array.isArray(row)&&row.some(value=>String(value??'').trim()));if(!records.length)throw new Error('File chưa có dòng công việc nào.');const parseDate=(value:unknown)=>{if(value instanceof Date&&!Number.isNaN(value.getTime()))return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;if(typeof value==='number'){const date=XLSX.SSF.parse_date_code(value);if(date)return `${date.y}-${String(date.m).padStart(2,'0')}-${String(date.d).padStart(2,'0')}`}const text=String(value??'').trim();const match=text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);if(match){const [,day,month,year]=match;return `${year.length===2?`20${year}`:year}-${month.padStart(2,'0')}-${day.padStart(2,'0')}`}return ''};const prepared=records.map((row,index)=>{const username=String(row[userCol]??'').trim().replace(/^@/,'');const person=people.find(p=>p.active&&p.role!=='admin'&&p.username.toLowerCase()===username.toLowerCase());const workType=String(row[typeCol]??'').trim(),title=String(row[titleCol]??'').trim(),deadline=parseDate(row[deadlineCol]);if(!person||!workType||!title||!deadline)throw new Error(`Dòng ${index+2}: kiểm tra Username, Kiểu công việc, Tên công việc và Deadline (dd/mm/yyyy).`);return {assigneeUserId:person.id,workType,title,description:String(descriptionCol<0?'':row[descriptionCol]??'').trim(),deadline}});let imported=0;for(const item of prepared){await api('/tasks',{method:'POST',body:JSON.stringify(item)});imported++}await refresh();setNotice(`Đã nhập và giao ${imported} công việc từ Excel.`)}catch(e){setError((e as Error).message||'Không thể đọc file Excel. Hãy dùng mẫu tải xuống và thử lại.')}};
 const saveProfile=async(e:FormEvent)=>{e.preventDefault();try{await api('/profile',{method:'PUT',body:JSON.stringify(profileForm)});setNotice('Đã lưu hồ sơ nhân viên và email khôi phục.');const r=await api<{profile:EmployeeProfile}>('/profile');setProfile(r.profile);}catch(e){setError((e as Error).message);}};
 const toggleTask=async(task:Task,completed:boolean)=>{if(completed&&!confirm(`Gửi “${task.title}” cho admin phê duyệt là đã hoàn thành?`))return;try{await api(`/tasks/${task.id}/completion`,{method:'PATCH',body:JSON.stringify({completed})});await refresh();setNotice('Đã gửi yêu cầu hoàn thành. Công việc được tính theo đúng thời điểm bạn gửi, kể cả khi admin duyệt sau deadline.');}catch(e){setError((e as Error).message);}};
 const reviewTask=async(task:Task,approved:boolean)=>{if(!approved&&!confirm(`Từ chối xác nhận hoàn thành công việc “${task.title}”? Nhân viên có thể gửi lại yêu cầu.`))return;try{await api(`/tasks/${task.id}/review`,{method:'PATCH',body:JSON.stringify({approved})});if(reviewToast?.id===task.id)setReviewToast(null);await refresh();setNotice(approved?'Đã duyệt hoàn thành công việc.':'Đã từ chối; nhân viên có thể gửi lại yêu cầu.');}catch(e){setError((e as Error).message);}};
 const approveFilteredTasks=async()=>{const ids=pendingApprovalTasks.map(t=>t.id);if(!ids.length)return;if(!confirm(`Phê duyệt ${ids.length} công việc đang chờ theo bộ lọc hiện tại?`))return;try{const result=await api<{approved:number}>('/tasks/review-bulk',{method:'PATCH',body:JSON.stringify({ids})});setReviewToast(null);await refresh();setNotice(`Đã phê duyệt ${result.approved} công việc.`)}catch(e){setError((e as Error).message)}};
 const deleteTask=async(task:Task)=>{setTaskDeletePassword('');setTaskDeleteRequest({ids:[task.id],label:task.title});};
