 const confirmTaskDeletion=async()=>{if(!taskDeleteRequest||!taskDeletePassword)return;try{if(taskDeleteRequest.ids.length===1){await api('/tasks/'+taskDeleteRequest.ids[0],{method:'DELETE',body:JSON.stringify({adminPassword:taskDeletePassword})});setNotice('Đã xóa công việc.')}else{const result=await api<{deleted:number}>('/tasks/bulk',{method:'DELETE',body:JSON.stringify({ids:taskDeleteRequest.ids,adminPassword:taskDeletePassword})});setSelectedTaskIds([]);setNotice('Đã xóa '+result.deleted+' công việc.')}setTaskDeleteRequest(null);setTaskDeletePassword('');await refresh()}catch(e){setError((e as Error).message)}};
 const todayIso=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh'}).format(now);const periodTasks=tasks.filter(t=>(!taskFilterUser||t.assigneeUserId===taskFilterUser)&&Number(t.deadline.slice(5,7))===taskMonth&&Number(t.deadline.slice(0,4))===taskYear);const allTaskTypes=[...new Set(tasks.map(t=>t.workType).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));const availableTaskTypes=[...new Set(periodTasks.map(t=>t.workType).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));const filteredTasks=periodTasks.filter(t=>{const overdue=t.deadline<todayIso&&!t.completedAt;const upcoming=t.deadline>=todayIso&&!t.completedAt;const pendingReview=Boolean(t.completionSubmittedAt&&!t.completedAt);const statusMatch=taskStatusFilter==="all"||(taskStatusFilter==="upcoming"&&upcoming)||(taskStatusFilter==="overdue"&&overdue)||(taskStatusFilter==="completed"&&Boolean(t.completedAt))||(taskStatusFilter==="pending-review"&&pendingReview);return statusMatch&&(!taskDueTodayOnly||(t.deadline===todayIso&&!t.completedAt&&!t.completionSubmittedAt))&&(!taskTypeFilter||t.workType===taskTypeFilter)});const taskPageSize=10,taskPageCount=Math.max(1,Math.ceil(filteredTasks.length/taskPageSize)),taskPageRows=filteredTasks.slice((taskPage-1)*taskPageSize,taskPage*taskPageSize);const pendingApprovalTasks=filteredTasks.filter(t=>t.completionSubmittedAt&&!t.completedAt);useEffect(()=>setTaskPage(1),[taskMonth,taskYear,taskFilterUser,taskTypeFilter,taskStatusFilter,taskDueTodayOnly]);useEffect(()=>{if(taskPage>taskPageCount)setTaskPage(taskPageCount)},[taskPage,taskPageCount]);

